function WeekView({ days, rows, onOpen, onAddAt }: {
  days: Date[]; rows: Row[]; onOpen: (r: Row) => void; onAddAt: (day: string) => void;
}) {
  const byDay = useMemo(() => groupByDay(rows), [rows]);
