function meta(row: Row): string {
  const marks: string[] = [hhmm(row.start)];
  if (row.kind === "occurrence") marks.push(t("home.chip.repeat"));
  if (row.action === "done") marks.push(t("home.chip.done"));
  if (row.action === "postponed") marks.push(t("home.chip.postponed"));
  if (row.action === "held") marks.push(t("home.chip.held"));
  if (row.action === "skipped") marks.push(t("home.chip.skipped"));
  return marks.join(" · ");
}

function ListView({ rows, onOpen }: { rows: Row[]; onOpen: (r: Row) => void }) {
  const groups = useMemo(() => [...groupByDay(rows)], [rows]);
  return (
    <div>
