}) {
  const [kind, setKind] = useState("event");
  const [title, setTitle] = useState("");
  const [start, setStart] = useState("");
  const [end, setEnd] = useState("");
  const [remind, setRemind] = useState("10");
  const [freq, setFreq] = useState("WEEKLY");
  const [interval, setInterval] = useState("1");
  const [byday, setByday] = useState<string[]>([]);
  const [duration, setDuration] = useState("60");
  const [ends, setEnds] = useState("never");
  const [until, setUntil] = useState("");
  const [count, setCount] = useState("");
  const [errors, setErrors] = useState<Errors>({});
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    if (initialStart === null) return;
    setKind("event"); setTitle(""); setStart(initialStart); setEnd(""); setRemind("10");
    setFreq("WEEKLY"); setInterval("1"); setByday([]); setDuration("60"); setEnds("never");
    setUntil(""); setCount(""); setErrors({}); setBusy(false);
  }, [initialStart]);

  const validate = (): Errors => {
    const e: Errors = {};
    if (title.trim().length < 1 || title.length > 200) e.title = t("home.add.errTitle");
    if (!start) e.start = t("home.add.errStart");
    if (kind === "event" && end && start && end <= start) e.end = t("home.add.errEnd");
    if (kind === "repeat") {
      if (!/^\d+$/.test(interval) || Number(interval) < 1) e.interval = t("home.add.errInterval");
      if (ends === "until" && (!until || (start && until < start))) e.until = t("home.add.errUntil");
      if (ends === "count" && (!/^\d+$/.test(count) || Number(count) < 1)) e.count = t("home.add.errCount");
    }
    return e;
  };

  const save = async () => {
    const found = validate();
    setErrors(found);
    if (Object.keys(found).length) return;
    setBusy(true);
    try {
      if (kind === "event") {
        await call("event.add", { title, start, ...(end ? { end } : {}), remind_before_minutes: Number(remind) });
      } else {
        await call("schedule.add", {
          title, start, freq, interval: Number(interval), duration_minutes: Number(duration) || 0,
          ...(freq === "WEEKLY" && byday.length ? { byday } : {}),
          ...(ends === "until" ? { until } : {}), ...(ends === "count" ? { count: Number(count) } : {}),
          remind_before_minutes: Number(remind),
        });
      }
      onSaved();
    } catch (error) {
      setErrors({ form: errorMessage(error, t("home.add.errServer")) });
      setBusy(false);
    }
  };

  return (
    <Dialog
