      title={t("home.add.title")}
      actions={<>
        <Button variant="ghost" onClick={onClose}>{t("home.add.cancel")}</Button>
        <Button variant="primary" disabled={busy} onClick={() => void save()}>{t("home.add.save")}</Button>
      </>}
    >
      <div className={styles.stack}>
        <Field label={t("home.add.kind")}>
          <Select value={kind} onValueChange={setKind} options={[
            { value: "event", label: t("home.add.kindEvent") }, { value: "repeat", label: t("home.add.kindRepeat") },
          ]} />
        </Field>
        <Field label={t("home.add.name")} error={errors.title}>
          <Input value={title} onChange={(e) => setTitle(e.target.value)} />
        </Field>
        <Field label={t("home.add.start")} error={errors.start}>
          <Input type="datetime-local" value={start} onChange={(e) => setStart(e.target.value)} />
        </Field>
        {kind === "event" ? (
          <Field label={t("home.add.end")} error={errors.end}>
            <Input type="datetime-local" value={end} onChange={(e) => setEnd(e.target.value)} />
          </Field>
        ) : (
          <>
            <Field label={t("home.add.duration")}>
              <Input type="number" min={0} max={1440} value={duration} onChange={(e) => setDuration(e.target.value)} />
            </Field>
            <Field label={t("home.add.freq")}>
              <Select value={freq} onValueChange={setFreq} options={[
                { value: "DAILY", label: t("home.add.freqDaily") }, { value: "WEEKLY", label: t("home.add.freqWeekly") },
                { value: "MONTHLY", label: t("home.add.freqMonthly") }, { value: "YEARLY", label: t("home.add.freqYearly") },
              ]} />
            </Field>
            <Field label={t("home.add.interval")} error={errors.interval}>
              <Input type="number" min={1} value={interval} onChange={(e) => setInterval(e.target.value)} />
            </Field>
            {freq === "WEEKLY" && (
              <Field label={t("home.add.byday")}>
                <div className={styles.toggles}>
                  {DAYS.map((d) => (
                    <Button key={d} variant={byday.includes(d) ? "primary" : "secondary"} aria-pressed={byday.includes(d)}
                      onClick={() => setByday(byday.includes(d) ? byday.filter((x) => x !== d) : [...byday, d])}>
                      {t(`home.weekday.${DAY_LABEL[d]}`)}
                    </Button>
                  ))}
                </div>
              </Field>
            )}
            <Field label={t("home.add.ends")}>
              <Select value={ends} onValueChange={setEnds} options={[
                { value: "never", label: t("home.add.endsNever") }, { value: "until", label: t("home.add.endsUntil") },
