// src/screens/home/model.ts
import { formatLocal, weekRange } from "@me/date-range";

export type Row = {
  kind: "event" | "occurrence";
  id: string;
  title: string;
  start: string;
  end: string | null;
  schedule_id?: string;
  occurrence_start?: string;
  action?: "done" | "postponed" | "skipped" | "held" | null;
  instance_id?: string | null;
  note?: string | null;
  remind_before_minutes: number;
};

export type View = "month" | "week" | "list";

const addDays = (d: Date, n: number) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);

export const dayKey = (d: Date) => formatLocal(d).slice(0, 10);

// 보기별 조회 범위(from 포함, to 미포함)와 월 격자의 날짜 칸들.
export function rangeOf(view: View, cursor: Date): { from: Date; to: Date; days: Date[] } {
  if (view === "week") {
    const { from, to } = weekRange(cursor, 0);
    return { from, to, days: Array.from({ length: 7 }, (_, i) => addDays(from, i)) };
  }
  const first = new Date(cursor.getFullYear(), cursor.getMonth(), 1);
  if (view === "list") {
    return { from: first, to: new Date(cursor.getFullYear(), cursor.getMonth() + 1, 1), days: [] };
  }
  const { from } = weekRange(first, 0);
  const weeks = Math.ceil(
    (((first.getDay() + 6) % 7) + new Date(cursor.getFullYear(), cursor.getMonth() + 1, 0).getDate()) / 7,
  );
  return { from, to: addDays(from, weeks * 7), days: Array.from({ length: weeks * 7 }, (_, i) => addDays(from, i)) };
}

export function shift(view: View, cursor: Date, direction: -1 | 1): Date {
  if (view === "week") return addDays(cursor, direction * 7);
  return new Date(cursor.getFullYear(), cursor.getMonth() + direction, 1);
}

export function groupByDay(rows: readonly Row[]): Map<string, Row[]> {
  const map = new Map<string, Row[]>();
  for (const row of rows) {
    const key = row.start.slice(0, 10);
    map.set(key, [...(map.get(key) ?? []), row]);
  }
  return map;
}

export const rowKey = (row: Row) => `${row.kind}:${row.id}:${row.occurrence_start ?? row.start}`;
export const hhmm = (text: string) => text.slice(11, 16);
export const minutesOfDay = (text: string) => Number(text.slice(11, 13)) * 60 + Number(text.slice(14, 16));


