import { appBridge } from "@lophn/app-ui";

export async function call(tool: string, input: Record<string, unknown>): Promise<unknown> {
  const bridge = appBridge();
  if (!bridge) throw new Error("unavailable: app bridge is unavailable");
  return await bridge.callTool(tool, input as never);
}

export function errorMessage(error: unknown, fallback: string): string {
  const message = error instanceof Error ? error.message : "";
  const match = /^[a-z_]+: (.+)$/s.exec(message);
  return match && /[가-힣]/.test(match[1]) ? match[1] : fallback;
}


